function pushAction(title,why,action,measure,page,item){var s=null;try{s=JSON.parse(localStorage.getItem(ACTION_STORE)||'null')}catch(e){}if(!s||s.version!==1||!s.reps)s={version:1,reps:{}};var b=s.reps[_rp2.rep]||(s.reps[_rp2.rep]={manual:[],state:{},events:[]}),ctx=context(),due=iso(ctx.selectedWeek.end||now()),existing=arr(b.manual).filter(function(t){var st=b.state&&b.state[t.id]||{};return t&&t.learningItemId===item&&st.status!=='completed'&&t.dueDate===due})[0];if(!existing){var task={id:'learn-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6),source:'manual',category:'coaching',tone:'info',score:155,title:title,why:why,action:action,measure:measure,dueDate:due,customer:'',orderNum:'',value:0,page:page||'learning',learningItemId:item};b.manual.push(task);b.events.push({type:'create',taskId:task.id,title:task.title,at:new Date().toISOString(),weekKey:ctx.selectedWeek.key||'',learningItemId:item});localStorage.setItem(ACTION_STORE,JSON.stringify(s))}return{existing:!!existing,due:due}}
