window._rp2LearningSubmitQuiz=function(encoded){var id=decodeURIComponent(encoded),q=qBy(id);if(!q)return;var correct=0,answered=0;q.questions.forEach(function(x,i){var el=document.getElementById('lp-q-'+i),v=el?String(el.value):'';if(v!=='')answered++;if(Number(v)===x[2])correct++});if(answered<q.questions.length)return;var score=Math.round(correct/q.questions.length*100),g=build(),b=g.bucket;b.data.quizzes.push({quizId:id,score:score,correct:correct,total:q.questions.length,at:new Date().toISOString()});g.lessons.filter(function(l){return l.quiz===id}).forEach(function(l){var st=b.data.lessons[l.id]||{};st.best=Math.max(n(st.best),score);st.attempts=n(st.attempts)+1;b.data.lessons[l.id]=st});log(b,'Knowledge check',q.title,score+'% · '+correct+' of '+q.questions.length+' correct.',id);save(_rp2.rep,b);window._rp2LearningModal={mode:'quiz',id:encoded,result:{score:score,correct:correct,total:q.questions.length}};rerender()};
